const HISTORY_KEY = 'atlantis:apiexplorer:history';
const HISTORY_MAX = 50;

function loadHistory(): HistoryEntry[] {
  try { return JSON.parse(localStorage.getItem(HISTORY_KEY) ?? '[]'); } catch { return []; }
}
function saveHistory(entries: HistoryEntry[]): void {
  try { localStorage.setItem(HISTORY_KEY, JSON.stringify(entries.slice(0, HISTORY_MAX))); } catch {}
}

function buildUrl(url: string, params: Param[]): string {
  const enabled = params.filter((p) => p.enabled && p.key.trim());
  if (!enabled.length) return url;
  const qs = enabled.map((p) => `${encodeURIComponent(p.key)}=${encodeURIComponent(p.value)}`).join('&');
  return url.includes('?') ? `${url}&${qs}` : `${url}?${qs}`;
}

function formatBytes(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

function tryPrettyJson(raw: string): { pretty: string; isJson: boolean } {
  try {
    const parsed = JSON.parse(raw);
    return { pretty: JSON.stringify(parsed, null, 2), isJson: true };
  } catch {
    return { pretty: raw, isJson: false };
  }
}

// ─── Syntax highlighting (pure CSS-in-JS, no deps) ───────────────────────────

function highlightJson(json: string): string {
  return json
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(
      /("(\\u[a-zA-Z0-9]{4}|\\[^u]|[^\\"])*"(\s*:)?|\b(true|false|null)\b|-?\d+(?:\.\d*)?(?:[eE][+\-]?\d+)?)/g,
      (match) => {
        if (/^"/.test(match)) {
          if (/:$/.test(match)) return `<span style="color:#79c0ff">${match}</span>`;
          return `<span style="color:#a5d6ff">${match}</span>`;
        }
        if (/true|false/.test(match)) return `<span style="color:#79c0ff">${match}</span>`;
        if (/null/.test(match)) return `<span style="color:#8b949e">${match}</span>`;
        return `<span style="color:#f2cc60">${match}</span>`;
      },
    );
}

