// ─── App ──────────────────────────────────────────────────────────────────────

interface AppProps {
  topBarRight?: React.ReactNode;
}

const EMPTY_REQ: RequestState = { method: 'GET', url: '', headers: [], params: [], body: '', bodyType: 'none' };
const API_STORAGE_KEY = 'toolkit:apiexplorer';

export default function App({ topBarRight }: AppProps) {
  const [request, setRequest] = useState<RequestState>(EMPTY_REQ);
  const [response, setResponse] = useState<ResponseState | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [reqTab, setReqTab] = useState<'params' | 'headers' | 'body'>('params');
  const [resTab, setResTab] = useState<'body' | 'headers'>('body');
  const [history, setHistory] = useState<HistoryEntry[]>(loadHistory);
  const [copied, setCopied] = useState(false);
  const [showSaveDialog, setShowSaveDialog] = useState(false);
  const abortRef = useRef<AbortController | null>(null);
  const loadedRef = useRef(false);

  useEffect(() => {
    getSetting(API_STORAGE_KEY).then((v) => {
      if (v) { try { setRequest(JSON.parse(v)); } catch { /* */ } }
      loadedRef.current = true;
    });
  }, []);

  useEffect(() => {
    if (!loadedRef.current) return;
    const id = setTimeout(() => putSetting(API_STORAGE_KEY, JSON.stringify(request)), 400);
    return () => clearTimeout(id);
  }, [request]);

  const handleNew = () => { setRequest(EMPTY_REQ); setResponse(null); setError(null); putSetting(API_STORAGE_KEY, ''); };

  const updateRequest = useCallback(<K extends keyof RequestState>(key: K, value: RequestState[K]) => {
    setRequest((prev) => ({ ...prev, [key]: value }));
  }, []);

  // ── KV helpers ──────────────────────────────────────────────────────────────

  const addHeader = () => updateRequest('headers', [...request.headers, { key: '', value: '', enabled: true }]);
  const removeHeader = (i: number) => updateRequest('headers', request.headers.filter((_, idx) => idx !== i));
  const updateHeader = (i: number, field: keyof Header, value: string | boolean) => {
    const next = [...request.headers];
    next[i] = { ...next[i], [field]: value };
    updateRequest('headers', next);
  };

  const addParam = () => updateRequest('params', [...request.params, { key: '', value: '', enabled: true }]);
  const removeParam = (i: number) => updateRequest('params', request.params.filter((_, idx) => idx !== i));
  const updateParam = (i: number, field: keyof Param, value: string | boolean) => {
    const next = [...request.params];
    next[i] = { ...next[i], [field]: value };
    updateRequest('params', next);
  };

  // ── Send ────────────────────────────────────────────────────────────────────

  const send = useCallback(async () => {
    if (!request.url.trim()) return;
    abortRef.current?.abort();
    const abort = new AbortController();
    abortRef.current = abort;

    setLoading(true);
    setError(null);
    setResponse(null);

    const t0 = performance.now();
    try {
      const url = buildUrl(request.url.trim(), request.params);
      const headers: Record<string, string> = {};
      request.headers.filter((h) => h.enabled && h.key.trim()).forEach((h) => {
        headers[h.key.trim()] = h.value;
      });

      let body: string | undefined;
      if (request.bodyType !== 'none' && request.method !== 'GET' && request.method !== 'HEAD') {
        body = request.body;
        if (request.bodyType === 'json' && !headers['Content-Type'] && !headers['content-type']) {
          headers['Content-Type'] = 'application/json';
        }
      }

      const res = await fetch(url, {
        method: request.method,
        headers,
        body,
        signal: abort.signal,
      });

      const rawBody = await res.text();
      const timing = Math.round(performance.now() - t0);
      const size = new TextEncoder().encode(rawBody).length;

      const resHeaders: Record<string, string> = {};
      res.headers.forEach((v, k) => { resHeaders[k] = v; });

      const next: ResponseState = {
        status: res.status, statusText: res.statusText,
        headers: resHeaders, body: rawBody,
        timing, size,
      };
      setResponse(next);

      const entry: HistoryEntry = {
        id: `${Date.now()}-${Math.random()}`,
        method: request.method,
        url: request.url,
        timestamp: Date.now(),
        status: res.status,
      };
      setHistory((prev) => {
        const next = [entry, ...prev];
        saveHistory(next);
        return next;
      });
    } catch (e: unknown) {
      if ((e as { name?: string }).name === 'AbortError') return;
      setError(e instanceof Error ? e.message : 'Request failed');
    } finally {
      setLoading(false);
    }
  }, [request]);

  // ── Keyboard shortcut: Ctrl/Cmd + Enter to send ──────────────────────────
  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      if ((e.ctrlKey || e.metaKey) && e.key === 'Enter') { e.preventDefault(); send(); }
    };
    window.addEventListener('keydown', handler);
    return () => window.removeEventListener('keydown', handler);
  }, [send]);

  // ── Copy response ────────────────────────────────────────────────────────
  const copyResponse = () => {
    if (!response) return;
    const { pretty } = tryPrettyJson(response.body);
    navigator.clipboard.writeText(pretty).then(() => {
      setCopied(true);
      setTimeout(() => setCopied(false), 1500);
    });
  };

  // ── Save / Load ──────────────────────────────────────────────────────────
  const [currentDoc, setCurrentDoc] = useState<{ id: string; name: string } | null>(null);

  const handleSave = async (name: string) => {
    const doc: SavedRequest = { version: 1, request };
    await saveDoc(APP_ID, name, JSON.stringify(doc));
    setShowSaveDialog(false);
    setCurrentDoc(null);
  };

  const handleUpdate = async () => {
    if (!currentDoc) return;
    const doc: SavedRequest = { version: 1, request };
    await updateDoc(currentDoc.id, currentDoc.name, JSON.stringify(doc));
    setShowSaveDialog(false);
  };

  const handleLoad = (content: string, docId?: string, docName?: string) => {
    setCurrentDoc(docId && docName ? { id: docId, name: docName } : null);
    try {
      const doc = JSON.parse(content) as SavedRequest;
      if (doc.version === 1) setRequest(doc.request);
    } catch {}
  };

  // ── Pretty-print response body ───────────────────────────────────────────
  const { pretty: prettyBody, isJson } = response ? tryPrettyJson(response.body) : { pretty: '', isJson: false };

  const enabledHeaderCount = request.headers.filter((h) => h.enabled && h.key.trim()).length;
  const enabledParamCount  = request.params.filter((p) => p.enabled && p.key.trim()).length;

  const topRight = (
    <div style={{ display: 'flex', alignItems: 'center', gap: theme.spacing.sm }}>
      <ToolbarBtn onClick={handleNew}><FilePlus size={13} /> New</ToolbarBtn>
      <DocumentsMenu appId={APP_ID} onLoad={handleLoad} />
      <ToolbarBtn onClick={() => setShowSaveDialog(true)}>
        <Save size={13} />
        Save
      </ToolbarBtn>
      {topBarRight}
    </div>
  );

  return (
    <Layout title="API Explorer" sidebar={<DevToolkitNav activeAppId="apiexplorer" />} topBarRight={topRight}>
      <Body>
        {/* History + Examples sidebar */}
        <HistorySidebar>
          <SidebarSection>
            History
            {history.length > 0 && (
              <SidebarClear title="Clear history" onClick={() => { setHistory([]); saveHistory([]); }}>
                <Trash2 size={12} />
              </SidebarClear>
            )}
          </SidebarSection>
          <SidebarList style={{ flex: history.length ? 1 : 0 }}>
            {history.length === 0 && (
              <div style={{ padding: '8px 12px', fontSize: 11, color: theme.colors.sidebarTextMuted }}>
                No requests yet
              </div>
            )}
            {history.map((entry) => (
              <HistoryItem
                key={entry.id}
                onClick={() => setRequest((prev) => ({ ...prev, method: entry.method, url: entry.url }))}
              >
                <HistoryItemTop>
                  {entry.status && <StatusDot status={entry.status} />}
                  <MethodBadge method={entry.method}>{entry.method}</MethodBadge>
                  <HistoryUrl>{entry.url.replace(/^https?:\/\//, '')}</HistoryUrl>
                </HistoryItemTop>
                <HistoryMeta>
                  {entry.status && <span>{entry.status} · </span>}
                  {new Date(entry.timestamp).toLocaleTimeString()}
                </HistoryMeta>
              </HistoryItem>
            ))}
          </SidebarList>

          <ExamplesSection>
            <SidebarSection>Examples</SidebarSection>
            {EXAMPLE_REQUESTS.map((ex) => (
              <ExampleItem key={ex.label} onClick={() => setRequest(ex.req)}>
                <MethodBadge method={ex.req.method}>{ex.req.method}</MethodBadge>
                <ExampleLabel>{ex.label}</ExampleLabel>
              </ExampleItem>
            ))}
          </ExamplesSection>
        </HistorySidebar>

        {/* Main panel */}
        <MainPanel>
          {/* URL bar */}
          <RequestBar>
            <MethodSelect
              method={request.method}
              value={request.method}
              onChange={(e) => updateRequest('method', e.target.value as Method)}
            >
              {(['GET','POST','PUT','PATCH','DELETE','HEAD','OPTIONS'] as Method[]).map((m) => (
                <option key={m} value={m}>{m}</option>
              ))}
            </MethodSelect>
            <UrlInput
              value={request.url}
              onChange={(e) => updateRequest('url', e.target.value)}
              placeholder="https://api.example.com/endpoint"
              onKeyDown={(e) => { if (e.key === 'Enter' && !e.shiftKey) send(); }}
            />
            <SendBtn loading={loading} onClick={send} disabled={loading}>
              <Send size={14} />
              {loading ? 'Sending…' : 'Send'}
            </SendBtn>
          </RequestBar>

          {/* Request + Response panes */}
          <PaneArea>
            {/* Request */}
            <RequestPane>
              <TabBar>
                <Tab active={reqTab === 'params'} onClick={() => setReqTab('params')}>
                  Params
                  {enabledParamCount > 0 && <TabBadge>{enabledParamCount}</TabBadge>}
                </Tab>
                <Tab active={reqTab === 'headers'} onClick={() => setReqTab('headers')}>
                  Headers
                  {enabledHeaderCount > 0 && <TabBadge>{enabledHeaderCount}</TabBadge>}
                </Tab>
                <Tab active={reqTab === 'body'} onClick={() => setReqTab('body')}>Body</Tab>
              </TabBar>

              {reqTab === 'params' && (
                <KVEditor>
                  {request.params.map((p, i) => (
                    <KVRow key={i}>
                      <KVCheck type="checkbox" checked={p.enabled} onChange={(e) => updateParam(i, 'enabled', e.target.checked)} />
                      <KVInput mono placeholder="key" value={p.key} onChange={(e) => updateParam(i, 'key', e.target.value)} />
                      <KVInput mono placeholder="value" value={p.value} onChange={(e) => updateParam(i, 'value', e.target.value)} />
                      <KVRemove onClick={() => removeParam(i)}><Trash2 size={12} /></KVRemove>
                    </KVRow>
                  ))}
                  <AddRowBtn onClick={addParam}><Plus size={12} /> Add param</AddRowBtn>
                </KVEditor>
              )}

              {reqTab === 'headers' && (
                <KVEditor>
                  {request.headers.map((h, i) => (
                    <KVRow key={i}>
                      <KVCheck type="checkbox" checked={h.enabled} onChange={(e) => updateHeader(i, 'enabled', e.target.checked)} />
                      <KVInput mono placeholder="Header-Name" value={h.key} onChange={(e) => updateHeader(i, 'key', e.target.value)} />
                      <KVInput mono placeholder="value" value={h.value} onChange={(e) => updateHeader(i, 'value', e.target.value)} />
                      <KVRemove onClick={() => removeHeader(i)}><Trash2 size={12} /></KVRemove>
                    </KVRow>
                  ))}
                  <AddRowBtn onClick={addHeader}><Plus size={12} /> Add header</AddRowBtn>
                </KVEditor>
              )}

              {reqTab === 'body' && (
                <BodyEditorWrap>
                  <BodyTypeBar>
                    <BodyTypeLabel>Body type:</BodyTypeLabel>
                    {(['none', 'json', 'text', 'form'] as const).map((t) => (
                      <BodyTypeBtn key={t} active={request.bodyType === t} onClick={() => updateRequest('bodyType', t)}>
                        {t}
                      </BodyTypeBtn>
                    ))}
                  </BodyTypeBar>
                  {request.bodyType !== 'none' ? (
                    <BodyTextarea
                      value={request.body}
                      onChange={(e) => updateRequest('body', e.target.value)}
                      placeholder={request.bodyType === 'json' ? '{\n  "key": "value"\n}' : 'Request body…'}
                      spellCheck={false}
                    />
                  ) : (
                    <EmptyPane style={{ flex: 1 }}>
                      <EmptyIcon>⊘</EmptyIcon>
                      <span>No body</span>
                    </EmptyPane>
                  )}
                </BodyEditorWrap>
              )}
            </RequestPane>

            {/* Response */}
            <ResponsePane>
              {error && (
                <>
                  <ResponseMeta>
                    <StatusBadge status={0}>Error</StatusBadge>
                    <MetaLabel>{error}</MetaLabel>
                  </ResponseMeta>
                  <EmptyPane>
                    <EmptyIcon>⚠</EmptyIcon>
                    <span style={{ color: '#f85149' }}>{error}</span>
                    <span style={{ fontSize: 12, marginTop: 4 }}>
                      Check the URL or CORS headers on the server.
                    </span>
                  </EmptyPane>
                </>
              )}

              {!response && !error && !loading && (
                <EmptyPane>
                  <EmptyIcon>🛰</EmptyIcon>
                  <span>Hit Send to fire a request</span>
                  <span style={{ fontSize: 12 }}>⌘↵ / Ctrl↵ to send</span>
                </EmptyPane>
              )}

              {loading && (
                <EmptyPane>
                  <EmptyIcon style={{ animation: 'spin 1s linear infinite' }}>⟳</EmptyIcon>
                  <span>Waiting for response…</span>
                  <style>{`@keyframes spin { to { transform: rotate(360deg); } }`}</style>
                </EmptyPane>
              )}

              {response && !loading && (
                <>
                  <ResponseMeta>
                    <StatusBadge status={response.status}>
                      {response.status} {response.statusText}
                    </StatusBadge>
                    <MetaLabel><Clock size={11} style={{ display: 'inline', marginRight: 3 }} />{response.timing} ms</MetaLabel>
                    <MetaLabel>{formatBytes(response.size)}</MetaLabel>
                    <CopyBtn copied={copied} onClick={copyResponse}>
                      {copied ? <><Check size={11} /> Copied</> : <><Copy size={11} /> Copy</>}
                    </CopyBtn>
                  </ResponseMeta>

                  <TabBar>
                    <Tab active={resTab === 'body'} onClick={() => setResTab('body')}>Body</Tab>
                    <Tab active={resTab === 'headers'} onClick={() => setResTab('headers')}>
                      Headers
                      <TabBadge>{Object.keys(response.headers).length}</TabBadge>
                    </Tab>
                  </TabBar>

                  {resTab === 'body' && (
                    <ResponseBody>
                      {isJson ? (
                        <CodeBlock dangerouslySetInnerHTML={{ __html: highlightJson(prettyBody) }} />
                      ) : (
                        <CodeBlock>{prettyBody}</CodeBlock>
                      )}
                    </ResponseBody>
                  )}

                  {resTab === 'headers' && (
                    <ResponseBody>
                      <HeadersTable>
                        {Object.entries(response.headers).map(([k, v]) => (
                          <HeaderRow key={k}>
                            <HeaderKey>{k}</HeaderKey>
                            <HeaderValue>{v}</HeaderValue>
                          </HeaderRow>
                        ))}
                      </HeadersTable>
                    </ResponseBody>
                  )}
                </>
              )}
            </ResponsePane>
          </PaneArea>
        </MainPanel>
      </Body>

      {showSaveDialog && (
        <SaveDialog onSave={handleSave} onUpdate={handleUpdate} existingDoc={currentDoc ?? undefined} onCancel={() => setShowSaveDialog(false)} />
      )}
    </Layout>
  );
}
